from flask import Flask, request, redirect, jsonify
import requests
import urllib.parse
import re

app = Flask(__name__)

# Internal service registry for microservice communication
SERVICE_REGISTRY = {
    'auth': 'http://10.0.1.50:8080',
    'billing': 'http://10.0.1.51:8080',
    'notifications': 'http://10.0.1.52:8080',
    'metadata': 'http://169.254.170.2'  # ECS task metadata endpoint
}

# Allowlist for redirect domains (incomplete validation)
ALLOWED_REDIRECT_HOSTS = ['app.example.com', 'login.example.com', 'cdn.example.com']

def is_safe_redirect(url):
    """Validate redirect URL - checks scheme and host"""
    try:
        parsed = urllib.parse.urlparse(url)
        if parsed.scheme not in ('http', 'https', ''):
            return False
        if parsed.hostname and parsed.hostname in ALLOWED_REDIRECT_HOSTS:
            return True
        # Allow relative URLs
        if not parsed.scheme and not parsed.hostname:
            return True
        return False
    except Exception:
        return False

@app.route('/login/callback')
def login_callback():
    """OAuth callback handler with redirect"""
    next_url = request.args.get('next', '/')
    token = request.args.get('token', '')

    # Validate the redirect target
    if not is_safe_redirect(next_url):
        return jsonify({'error': 'Invalid redirect URL'}), 400

    return redirect(next_url)

@app.route('/api/proxy')
def service_proxy():
    """Internal service proxy - fetches data from internal services"""
    service_url = request.args.get('url', '')
    callback_url = request.args.get('callback', '')

    # Block obvious SSRF attempts to cloud metadata
    blocked_patterns = ['169.254.169.254', 'metadata.google', 'metadata.azure']
    if any(pattern in service_url for pattern in blocked_patterns):
        return jsonify({'error': 'Blocked request'}), 403

    try:
        # Fetch from the requested internal service
        resp = requests.get(service_url, timeout=5, allow_redirects=True)
        data = resp.text

        # If callback URL provided, send results there (webhook pattern)
        if callback_url:
            requests.post(callback_url, json={'result': data}, timeout=5)
            return jsonify({'status': 'sent to callback'})

        return jsonify({'data': data})
    except requests.exceptions.RequestException as e:
        return jsonify({'error': str(e)}), 502

@app.route('/api/health')
def health_check():
    """Health check endpoint that queries ECS metadata"""
    try:
        meta = requests.get('http://169.254.170.2/v2/metadata', timeout=2)
        return jsonify({'status': 'healthy', 'task_arn': meta.json().get('TaskARN', 'unknown')})
    except Exception:
        return jsonify({'status': 'healthy', 'task_arn': 'unavailable'})

@app.route('/api/fetch-config')
def fetch_config():
    """Fetch configuration from internal config service"""
    config_host = request.args.get('host', '10.0.1.100')
    config_path = request.args.get('path', '/config/app.json')

    # Validate host looks like internal IP
    if not re.match(r'^10\.0\.\d+\.\d+$', config_host):
        # Allow redirect-based resolution for service mesh
        if not re.match(r'^[a-z\-]+\.internal\.local$', config_host):
            return jsonify({'error': 'Invalid config host'}), 400

    url = f'http://{config_host}:8080{config_path}'
    try:
        resp = requests.get(url, timeout=5, allow_redirects=True)
        return jsonify({'config': resp.json()})
    except Exception as e:
        return jsonify({'error': f'Config fetch failed: {e}'}), 502

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
